  "help.type.cant_login": "ログインできません",
  "help.type.email_issue": "メールの問題",
  "help.type.security": "セキュリティ",
  "help.type.other": "その他",
  "help.faq.cantLogin.q": "アカウントにアクセスできません",
  "help.faq.cantLogin.a": "正しいメールアドレスとパスワードを使用しているか確認してください。パスワードを忘れた場合は、ログイン画面の「パスワードを忘れました？」をクリックしてください。問題が続く場合は、サポートチケットを作成してください。",
  "help.faq.notReceiving.q": "メールが届きません",
  "help.faq.notReceiving.a": "まずスパムフォルダを確認してください。ストレージがい��ぱいでないことを��認してください。問題が続く場合は、送信者が正しいアドレスを持っているか確認し、チケットを作成してください。",
  "help.faq.cantSend.q": "メールを送信できません",
  "help.faq.cantSend.a": "インターネット接続と受信者のアドレスが正しいか確認してください。添付ファイルが25MBを超えていないか確認してください。数分後に再試行してください。",
  "help.faq.forgotPassword.q": "パスワードを忘れました",
  "help.faq.forgotPassword.a": "ログイン画面で「パスワードを忘れました？」をクリックし、リカバリーメールでパスワードをリセットする手順に従ってください。",
  "help.faq.accountSecurity.q": "アカウントが侵害されたと思います",
  "help.faq.accountSecurity.a": "すぐにパスワードを変更してください。自分が送信していないメッセージが送信済みフォルダにないか確認してください。設定 > セキュリティで二段階認証を有効にしてください。必要に応じて、緊急チケットを作成してください。",
  "help.faq.appAccess.q": "携帯電話でアプリにアクセスするには？",
  "help.faq.appAccess.a": "ブラウザで chatyy.com.br にアクセスして Chatyy を使うか、お使いのデバイスのアプリストアからアプリをダウンロードできます。",
  "privacy.title": "プライバシーポリシー",
  "privacy.subtitle": "データをどのように保護し、扱うか",
  "privacy.lastUpdated": "最終更新: 2026年3月",
  "privacy.dataCollection.title": "データの収集",
  "privacy.dataCollection.body": "メールサービスに必要な情報のみを収集します: あなたの名前、メールアドレス、送受信されたメッセージの内容。マーケティング目的で第三者に個人データを販売または共有することはありません。",
  "privacy.dataUsage.title": "データの使用方法",
  "privacy.dataUsage.body": "あなたのデータは、メールサービスの運営と改善のためにのみ使用されます。メッセージの配信、スパムフィルタリング、AI機能（あなたの同意のもと）およびアカウントのセキュリティを含みます。",
  "privacy.dataSecurity.title": "データのセキュリティ",
  "privacy.dataSecurity.body": "業界標準の暗号化（TLS/SSL）を使用して、すべてのデータを転送中および静止中に保護します。セッションは暗号化トークンとCSRF保護で保護されています。セキュリティプラクティスを定期的に監査しています。",
  "privacy.cookies.title": "クッキーとローカルストレージ",
  "privacy.cookies.body": "セッションを維持し、好み（テーマ、言語）を記憶し、スムーズな体験を提供するために、必須のクッキーとローカルストレージを使用します。サードパーティのトラッキングクッキーは使用していません。",
  "privacy.thirdParties.title": "サードパーティサービス",
  "privacy.thirdParties.body": "特定の機能（AI（Anthropic Claude）やプッシュ通知など）のためにサードパーティサービスを使用することがあります。これらのサービスは独自のプライバシーポリシーに従い、必要最低限のデータのみを処理します。",
  "privacy.rights.title": "あなたの権利",
  "privacy.rights.body": "いつでも個人データにアクセス、修正、エクスポート、または削除する権利があります。設定でデータを管理するか、サポートに連絡してください。",
  "privacy.contact.title": "お問い合わせ",
  "privacy.contact.body": "プライバシーに関する質問やデータリクエストについては、privacy@chatyy.com.brまでご連絡ください。30日以内にお返事します。",
  "terms.title": "サービス利用規約",
  "terms.subtitle": "Chatyyの利用ガイドライン",
  "terms.lastUpdated": "最終更新: 2026年3月",
  "terms.acceptance.title": "利用規約の承諾",
  "terms.acceptance.body": "Chatyyにアクセスまたは使用することで、これらのサービス利用規約に同意したことになります。これらの規約のいずれかに同意しない場合は、サービスを利用しないでください。",
  "terms.services.title": "サービスの説明",
  "terms.services.body": "Chatyyは、メールの送受信や管理、AI機能、カレンダーとの統合、ビデオ会議などのコミュニケーションサービスを提供します。",
  "terms.accounts.title": "ユーザーアカウント",
  "terms.accounts.body": "あなたは自分の認証情報のセキュリティを維持する責任があります。パスワードを共有したり、アカウントへの不正アクセスを許可したりしないでください。このサービスを利用するには、13歳以上である必要があります。",
  "terms.conduct.title": "適切な利用",
  "terms.conduct.body": "スパム、マルウェア、フィッシング、または違法なコンテンツを送信するためにサービスを使用しないことに同意します。他のユーザーのアカウントにアクセスしたり、サービスのインフラを妨害したりしないでください。",
  "terms.content.title": "コンテンツの所有権",
  "terms.content.body": "サービスを通じて作成し送信するすべてのコンテンツの所有権はあなたにあります。あなたのメールや添付ファイルに対する所有権を主張することはありません。サービスを提供するために必要に応じてコンテンツを処理することがあります。",
  "terms.limitation.title": "責任の制限",
  "terms.limitation.body": "Chatyyは「現状のまま」提供されます。99.9%の可用性を目指しますが、サービスの中断を保証するものではありません。サービスの使用に起因する間接的、偶発的、または結果的な損害については責任を負いません。",
  "terms.termination.title": "アカウントの終了",
  "terms.termination.body": "これらの規約に違反するアカウントを一時停止ま���は終了することがあります。設定からいつでもアカウントを削除できます。終了後、あなたのデータは30日以内に削除されます。",
  "terms.changes.title": "利用規約の変更",
  "terms.changes.body": "これらの規約は定期的に更新されることがあります。重要な変更については、メールまたはアプリ内通知でお知らせします。変更後の継続的な使用は、更新された規約の承諾を意味します。",
